"""Fail-closed license gate for the design-partner PyInstaller binary.

ADR-0011 §3.4 + BEAAA-567 §4 contract:

* Every binary invocation makes a TLS callback to the IFA license endpoint.
* The binary fails closed on validation failure, network unreachable,
  endpoint timeout, attestation signature invalid, or attestation expired.
* No offline grace period. No retry. No degraded scoring path.

This module is the *only* surface that imports the BEAAA-569 reference
client (``infra.license_validator.client``). Calibration paths
(``bin/are-scan``, ``harness/cli_runner``, in-agent scoring) MUST NOT
import it — calibration must remain byte-identical across distribution
modes (ADR-0011 §3.7 + §7 gate 2).

The endpoint host and the embedded public key come from build-time
config (``infra.dist._dist_config``), not from environment variables.
Build-time config is generated by ``infra.dist.build`` and baked into
the PyInstaller bundle (BEAAA-567 §4, BEAAA-569 setup notice).
"""
from __future__ import annotations

import sys
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol

# These imports must not pull in any local-try-it / in-agent runtime; the
# gate stays self-contained so a future audit can prove the gate cannot
# leak into the scoring path.
from infra.license_validator.attestation import load_public_key
from infra.license_validator.client import (
    LicenseClientConfig,
    LicenseValidationError,
    fetch_attestation,
)

GATE_FAIL_EXIT_CODE = 4
"""Exit code returned by the binary when the license gate refuses to score.

Distinct from ``bin/are-scan``'s 0/1/2/3 contract so operators can tell a
gate failure from an inputs failure. Documented in
``infra/dist/README.md``.
"""


class _DistConfigProto(Protocol):
    PARTNER_ID: str
    BINARY_BUILD_ID: str
    LICENSE_ENDPOINT_URL: str
    LICENSE_KEY: str
    PUBLIC_KEY_PEM: bytes
    REQUEST_TIMEOUT_SEC: float


@dataclass(frozen=True)
class GateOutcome:
    """Either ``ok=True`` (attestation verified) or a refusal reason."""

    ok: bool
    reason: str
    exit_code: int


def _load_dist_config() -> _DistConfigProto:
    """Import the baked-in dist config or fail loudly.

    The dist config is baked at PyInstaller time by
    ``infra/dist/build.py``. If it is missing, the binary was assembled
    incorrectly and must not score — refuse rather than reach for an
    environment-variable fallback (ADR-0011 §3.4 explicitly forbids env
    fallback for the endpoint host; we hold the same rule for partner
    identity, license key, and public key).
    """
    try:
        from infra.dist import _dist_config  # type: ignore[attr-defined]
    except ModuleNotFoundError as exc:
        raise LicenseValidationError(
            "dist config missing from bundle — refusing to score"
        ) from exc
    return _dist_config  # type: ignore[return-value]


def _materialise_public_key(pem_bytes: bytes) -> Path:
    """Write the bundled PEM bytes to a tmpfile and return the path.

    ``infra.license_validator.attestation.load_public_key`` reads from a
    filesystem path; PyInstaller's ``--onefile`` mode unpacks bundled
    data to a temp dir already, but we keep the public key as bytes in
    ``_dist_config`` so it is impossible to swap by replacing a sidecar
    file on disk. Writing once per process to ``_MEIPASS`` (when
    available) or ``/tmp`` is safe — the verifier checks ``key_id``
    against the embedded fingerprint.
    """
    base = Path(getattr(sys, "_MEIPASS", "/tmp"))
    target = base / "_ifa_pubkey.pem"
    if not target.exists():
        target.write_bytes(pem_bytes)
        target.chmod(0o400)
    return target


def check_license(*, scan_id: str | None = None) -> GateOutcome:
    """Run one license validation; return success or a refusal outcome.

    No retries, no caching, no offline grace. The caller (``are_scan_dist``)
    must exit on any non-``ok`` outcome before invoking the scoring path.
    """
    try:
        cfg_mod = _load_dist_config()
    except LicenseValidationError as exc:
        return GateOutcome(ok=False, reason=str(exc), exit_code=GATE_FAIL_EXIT_CODE)

    pubkey_path = _materialise_public_key(cfg_mod.PUBLIC_KEY_PEM)
    try:
        public_key = load_public_key(pubkey_path)
    except Exception as exc:  # noqa: BLE001 — bundle integrity boundary
        return GateOutcome(
            ok=False,
            reason=f"embedded public key unreadable: {exc.__class__.__name__}",
            exit_code=GATE_FAIL_EXIT_CODE,
        )

    config = LicenseClientConfig(
        endpoint_url=cfg_mod.LICENSE_ENDPOINT_URL,
        public_key=public_key,
        partner_id=cfg_mod.PARTNER_ID,
        binary_build_id=cfg_mod.BINARY_BUILD_ID,
        license_key=cfg_mod.LICENSE_KEY,
        timeout_sec=getattr(cfg_mod, "REQUEST_TIMEOUT_SEC", 10.0),
    )

    try:
        fetch_attestation(
            config=config,
            scan_id=scan_id or str(uuid.uuid4()),
        )
    except LicenseValidationError as exc:
        return GateOutcome(
            ok=False, reason=str(exc), exit_code=GATE_FAIL_EXIT_CODE
        )
    return GateOutcome(ok=True, reason="valid", exit_code=0)
